@staticmethod
def infrastructure_failure(result: dict[str, Any]) -> bool:
    combined = "\n".join(
        str(result.get(key, ""))
        for key in (
            "stdout",
            "stderr",
            "check_output",
            "error",
        )
    ).lower()

    markers = (
        "unicodeencodeerror",
        "charmap",
        "cp1252",
        "codec can't encode",
        "codec cannot encode",
    )
    return any(marker in combined for marker in markers)

